"use client"

import type { ComponentProps } from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

import { Button } from "@/registry/react/button"
import { Input } from "@/registry/react/input"
import { Textarea } from "@/registry/react/textarea"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./input-group.css"

function InputGroup({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="input-group"
      role="group"
      className={cn("np-input-group", className)}
      {...props}
    />
  )
}

const inputGroupAddonVariants = cva("np-input-group-addon", {
  variants: {
    align: {
      "inline-start": "",
      "inline-end": "np-input-group-addon-end",
      "block-start": "np-input-group-addon-block-start",
      "block-end": "np-input-group-addon-block-end",
    },
  },
  defaultVariants: {
    align: "inline-start",
  },
})

function InputGroupAddon({
  className,
  align = "inline-start",
  onClick,
  ...props
}: ComponentProps<"div"> & VariantProps<typeof inputGroupAddonVariants>) {
  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={align}
      className={cn(inputGroupAddonVariants({ align }), className)}
      onClick={(event) => {
        onClick?.(event)
        if (event.defaultPrevented) return
        if ((event.target as HTMLElement).closest("button")) {
          return
        }
        event.currentTarget.parentElement
          ?.querySelector<HTMLElement>("input, textarea")
          ?.focus()
      }}
      {...props}
    />
  )
}

function InputGroupButton({
  className,
  type = "button",
  variant = "ghost",
  size = "xs",
  ...props
}: Omit<ComponentProps<typeof Button>, "size" | "type"> & {
  size?: "xs" | "sm" | "icon-xs" | "icon-sm"
  type?: "button" | "submit" | "reset"
}) {
  return (
    <Button
      type={type}
      variant={variant}
      size={size}
      className={cn("np-input-group-button", className)}
      {...props}
    />
  )
}

function InputGroupText({ className, ...props }: ComponentProps<"span">) {
  return (
    <span
      data-slot="input-group-text"
      className={cn("np-input-group-text", className)}
      {...props}
    />
  )
}

function InputGroupInput({
  className,
  ...props
}: ComponentProps<typeof Input>) {
  return (
    <Input
      data-slot="input-group-control"
      className={cn("np-input-group-input", className)}
      {...props}
    />
  )
}

function InputGroupTextarea({
  className,
  ...props
}: ComponentProps<typeof Textarea>) {
  return (
    <Textarea
      data-slot="input-group-control"
      className={cn("np-input-group-textarea", className)}
      {...props}
    />
  )
}

export {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupText,
  InputGroupInput,
  InputGroupTextarea,
  inputGroupAddonVariants,
}

/* nepui — Input Group */

.np-input-group,
[data-np-input-group] {
  --np-input-group-height: calc(var(--np-spacing, 0.25rem) * 8);
  --np-input-group-radius: var(--np-radius-md);
  --np-input-group-border: var(--np-input, var(--np-border));
  --np-input-group-bg: transparent;
  --np-input-group-disabled-bg: color-mix(
    in oklch,
    var(--np-input-group-border),
    transparent 50%
  );
  --np-input-group-invalid-border: var(--np-destructive);
  --np-input-group-invalid-ring: color-mix(
    in oklch,
    var(--np-destructive),
    transparent 80%
  );

  position: relative;
  display: flex;
  align-items: center;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: var(--np-input-group-height);

  border: 1px solid var(--np-input-group-border);
  border-radius: var(--np-input-group-radius);
  background: var(--np-input-group-bg);

  outline: none;
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}

/* Focus  */
:is(.np-input-group, [data-np-input-group]):has(
  :where(
    .np-input-group-input,
    .np-input-group-textarea,
    [data-np-input-group-input],
    [data-np-input-group-textarea]
  ):focus-visible
) {
  border-color: var(--np-ring);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

/* Disabled */
:is(.np-input-group, [data-np-input-group]):has(
  :where(
    .np-input-group-input,
    .np-input-group-textarea,
    [data-np-input-group-input],
    [data-np-input-group-textarea]
  ):is(:disabled, [data-disabled], [aria-disabled="true"])
) {
  background: var(--np-input-group-disabled-bg);
  opacity: 0.5;
  pointer-events: none;
}

/* Invalid. */
:is(.np-input-group, [data-np-input-group]):has(
  [aria-invalid="true"],
  [data-invalid]
),
:is(.np-input-group, [data-np-input-group])[data-invalid] {
  border-color: var(--np-input-group-invalid-border);
  box-shadow: 0 0 0 3px var(--np-input-group-invalid-ring);
}

/* Taller layouts: a textarea, or an addon above / below the control */
:is(.np-input-group, [data-np-input-group]):has(
  > :is(textarea, .np-input-group-textarea, [data-np-input-group-textarea])
) {
  height: auto;
}

:is(.np-input-group, [data-np-input-group]):has(
  > :is(
    .np-input-group-addon-block-start,
    .np-input-group-addon-block-end,
    [data-align="block-start"],
    [data-align="block-end"]
  )
) {
  flex-direction: column;
  height: auto;
}

/* Room next to an addon, and above / below block addons */
:is(.np-input-group, [data-np-input-group]):has(
    > :is(.np-input-group-addon-block-end, [data-align="block-end"])
  )
  > input {
  padding-top: calc(var(--np-spacing, 0.25rem) * 3);
}

:is(.np-input-group, [data-np-input-group]):has(
    > :is(.np-input-group-addon-block-start, [data-align="block-start"])
  )
  > input {
  padding-bottom: calc(var(--np-spacing, 0.25rem) * 3);
}

:is(.np-input-group, [data-np-input-group]):has(
    > :is(.np-input-group-addon-end, [data-align="inline-end"])
  )
  > input {
  padding-right: calc(var(--np-spacing, 0.25rem) * 1.5);
}

:is(.np-input-group, [data-np-input-group]):has(
    > :is(
      .np-input-group-addon:not(
        .np-input-group-addon-end,
        .np-input-group-addon-block-start,
        .np-input-group-addon-block-end
      ),
      [data-np-input-group-addon]:not([data-align]),
      [data-align="inline-start"]
    )
  )
  > input {
  padding-left: calc(var(--np-spacing, 0.25rem) * 1.5);
}

:is(.np-input-group, [data-np-input-group])
  :is(
    .np-input-group-input,
    .np-input-group-textarea,
    [data-np-input-group-input],
    [data-np-input-group-textarea]
  ),
:is(.np-input-group, [data-np-input-group])
  :is(
    .np-input-group-input,
    .np-input-group-textarea,
    [data-np-input-group-input],
    [data-np-input-group-textarea]
  ):is(
    :focus-visible,
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-invalid="true"],
    [data-invalid]
  ) {
  flex: 1;
  min-width: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

:is(.np-input-group, [data-np-input-group])
  :is(.np-input-group-textarea, [data-np-input-group-textarea]) {
  resize: none;
  padding-block: calc(var(--np-spacing, 0.25rem) * 2);
}

/* InputGroupAddon */

.np-input-group-addon,
[data-np-input-group-addon] {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--np-spacing, 0.25rem) * 2);
  height: auto;
  padding-block: calc(var(--np-spacing, 0.25rem) * 1.5);
  padding-inline: calc(var(--np-spacing, 0.25rem) * 2) 0;
  order: -9999;

  color: var(--np-muted-foreground);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: text;
  -webkit-user-select: none;
  user-select: none;
}

:is(.np-input-group-addon, [data-np-input-group-addon]) > svg {
  flex-shrink: 0;
}

:is(.np-input-group-addon, [data-np-input-group-addon])
  > svg:not([class*="size-"]) {
  width: 1rem;
  height: 1rem;
}

:is(.np-input-group-addon, [data-np-input-group-addon]) > kbd {
  border-radius: max(
    0px,
    calc(var(--np-radius, var(--np-radius-md, 0.5rem)) - 5px)
  );
}

/* inline-start (the default): pull a button / key closer to the edge */
:is(.np-input-group-addon, [data-np-input-group-addon]):not(
    .np-input-group-addon-end,
    .np-input-group-addon-block-start,
    .np-input-group-addon-block-end,
    [data-align="inline-end"],
    [data-align="block-start"],
    [data-align="block-end"]
  ):has(> button) {
  margin-inline-start: -0.2rem;
}

:is(.np-input-group-addon, [data-np-input-group-addon]):not(
    .np-input-group-addon-end,
    .np-input-group-addon-block-start,
    .np-input-group-addon-block-end,
    [data-align="inline-end"],
    [data-align="block-start"],
    [data-align="block-end"]
  ):has(> kbd) {
  margin-inline-start: -0.15rem;
}

/* inline-end */
.np-input-group-addon-end,
:is(
  .np-input-group-addon,
  [data-np-input-group-addon]
)[data-align="inline-end"] {
  order: 9999;
  margin-inline: 0;
  padding-inline: 0 calc(var(--np-spacing, 0.25rem) * 2);
}

:is(
  .np-input-group-addon-end,
  :is(
    .np-input-group-addon,
    [data-np-input-group-addon]
  )[data-align="inline-end"]
):has(> button) {
  margin-inline-end: -0.2rem;
}

:is(
  .np-input-group-addon-end,
  :is(
    .np-input-group-addon,
    [data-np-input-group-addon]
  )[data-align="inline-end"]
):has(> kbd) {
  margin-inline-end: -0.15rem;
}

/* block-start */
.np-input-group-addon-block-start,
:is(
  .np-input-group-addon,
  [data-np-input-group-addon]
)[data-align="block-start"] {
  order: -9999;
  justify-content: flex-start;
  width: 100%;
  margin-inline: 0;
  padding-block: calc(var(--np-spacing, 0.25rem) * 2) 0;
  padding-inline: 0.625rem;
}

/* block-end */
.np-input-group-addon-block-end,
:is(
  .np-input-group-addon,
  [data-np-input-group-addon]
)[data-align="block-end"] {
  order: 9999;
  justify-content: flex-start;
  width: 100%;
  margin-inline: 0;
  padding-block: 0 calc(var(--np-spacing, 0.25rem) * 2);
  padding-inline: 0.625rem;
}

:is(.np-input-group, [data-np-input-group])[data-disabled="true"]
  :is(.np-input-group-addon, [data-np-input-group-addon]) {
  opacity: 0.5;
}

/* InputGroupText */

.np-input-group-text,
[data-np-input-group-text] {
  display: flex;
  align-items: center;
  gap: calc(var(--np-spacing, 0.25rem) * 2);
  color: var(--np-muted-foreground);
  font-size: 0.875rem;
}

:is(.np-input-group-text, [data-np-input-group-text]) svg {
  pointer-events: none;
}

:is(.np-input-group-text, [data-np-input-group-text])
  svg:not([class*="size-"]) {
  width: 1rem;
  height: 1rem;
}

/* InputGroupButton (a Button inside an addon) */

.np-input-group-button,
[data-np-input-group-button] {
  box-shadow: none;
  gap: calc(var(--np-spacing, 0.25rem) * 2);
  font-size: 0.875rem;
}

:is(.np-input-group-button, [data-np-input-group-button]):is(
  .np-button-xs,
  [data-size="xs"]
) {
  --np-button-padding-x: calc(var(--np-spacing, 0.25rem) * 1.5);
  --np-button-icon-size: 0.875rem;
  gap: 0.25rem;
}

/* Dark */

:is(.dark, [data-theme="dark"]) :is(.np-input-group, [data-np-input-group]) {
  --np-input-group-bg: color-mix(
    in oklab,
    var(--np-input-group-border) 30%,
    transparent
  );
  --np-input-group-disabled-bg: color-mix(
    in oklab,
    var(--np-input-group-border) 80%,
    transparent
  );
  --np-input-group-invalid-ring: color-mix(
    in oklab,
    var(--np-destructive) 40%,
    transparent
  );
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"])
    :is(.np-input-group, [data-np-input-group]) {
    --np-input-group-bg: color-mix(
      in oklab,
      var(--np-input-group-border) 30%,
      transparent
    );
    --np-input-group-disabled-bg: color-mix(
      in oklab,
      var(--np-input-group-border) 80%,
      transparent
    );
    --np-input-group-invalid-ring: color-mix(
      in oklab,
      var(--np-destructive) 40%,
      transparent
    );
  }
}
